CREATE TABLE IF NOT EXISTS notifications(id UUID PRIMARY KEY,recipient_id UUID NOT NULL,type VARCHAR(50) NOT NULL,message TEXT NOT NULL,link VARCHAR(300),is_read BOOLEAN NOT NULL DEFAULT FALSE); CREATE TABLE IF NOT EXISTS announcements(id UUID PRIMARY KEY,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,audience VARCHAR(30) NOT NULL,role VARCHAR(30),published_by UUID NOT NULL,published_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
